"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[7585],{7878(e){e.exports=JSON.parse('{"title":"Figma\uc758 TypeScript \uc804\ud658 \uc5ec\uc815","date":"2024-05-15","coverUrl":null,"html":"<h2 data-notion-block-id=\\"e2c4e61b-a6c3-4ccb-9d64-dd642004b9da\\" id=\\"e2c4e61b-a6c3-4ccb-9d64-dd642004b9da\\">Figma\uc758 TypeScript \uc804\ud658 \uc5ec\uc815</h2><a href=\\"https://www.figma.com/blog/figmas-journey-to-typescript-compiling-away-our-custom-programming-language/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.figma.com/blog/figmas-journey-to-typescript-compiling-away-our-custom-programming-language/</a><p data-notion-block-id=\\"ee32155e-7082-448c-bdd4-dc8a52a9cc9c\\"><b>\uc2ec\uc724\uc12d</b>: Figma\uc5d0\uc11c Skew\uc5b8\uc5b4\uc5d0\uc11c TypeScript\ub85c \ubcc0\uacbd\ud558\uc600\ub2e4\ub294 \uc7ac\ubc0c\ub294 \uae00\uc785\ub2c8\ub2e4. Skew to TypeScript \ud504\ub85c\uc81d\ud2b8\uac00 \uc810\uc9c4\uc801\uc73c\ub85c \uc5b4\ub5bb\uac8c \uc774\ub8e8\uc5b4\uc838\uc788\ub294\uc9c0, \ud2b8\ub79c\uc2a4\ud30c\uc77c\ub7ec \uac1c\ub150\uacfc \uc18c\uc2a4\ub9f5, \ud2b8\ub9ac \uc170\uc774\ud0b9\uc744 \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. \ub2e8\uc9c0 \uc810\uc9c4\uc801\uc73c\ub85c TypeScript\ub85c \ubcc0\uacbd\ud558\ub294 \ud504\ub85c\uc81d\ud2b8\uc5d0 \ub300\ud55c \uae00\uc774\uc9c0\ub9cc \uc548\uc5d0 \ub4e4\uc5b4\uac04 \uac1c\ub150\uc744 \ub9c1\ud06c\uc640 \ud568\uaed8 \uc124\uba85\ud558\uace0 \uc788\uc73c\ubbc0\ub85c \uc2dc\uac04\uc744 \ub4e4\uc5ec \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"c591a4a0-9749-47c1-9c95-4838fa55356d\\" id=\\"c591a4a0-9749-47c1-9c95-4838fa55356d\\">Monkey Patch\ub97c \ud558\uc9c0 \ub9c8\uc138\uc694.</h2><a href=\\"https://kettanaito.com/blog/why-patching-globals-is-harmful\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kettanaito.com/blog/why-patching-globals-is-harmful</a><p data-notion-block-id=\\"09e3c047-26d3-47fb-8fdf-c421190bdf47\\"><b>\uc2ec\uc724\uc12d</b>: \uc774\uc804\uc5d0 \uac00\uc838\uc628 \uc5ec\ub7ec \uae00\uacfc \ube44\uc2b7\ud55c \uc8fc\uc7a5\uc774 \ub2f4\uae34 \uae00\uc785\ub2c8\ub2e4(<a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6901b4f3e8b9a0e48601ad787#6e1950cf-ceb7-418a-a85a-e4b7aef10d94\\">React 18\uc5d0\uc11c\uc758 \ubd88\ub9cc</a>, <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#ec85017c-c8bc-46e1-abbe-e69801686efa\\">\ucd94\uc0c1\ud654\ub294 \uc801\uc808\ud558\uac8c</a>). \uadf8 \uc911\uc5d0\uc11c Monkey patch, \uc989 global API(\uc5b4\ub5bb\uac8c \ubcf4\uba74 \ud50c\ub7ab\ud3fc API\ub77c\uace0 \ubcfc \uc218 \uc788\uaca0\ub124\uc694)\ub97c \uc784\uc758 \uc218\uc815\ud558\uba74 \ub098\uc05c \uc810(\uc720\uc9c0 \ubcf4\uc218 \ud798\ub4e6, \ub77d\uc778 \ud6a8\uacfc, \ucd94\uac00\ub85c \ubc30\uc6cc\uc57c \ud55c\ub2e4\ub294 \uc810)\uc744 \ub9d0\ud569\ub2c8\ub2e4. \uc774\uc804\uc758 <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#ec85017c-c8bc-46e1-abbe-e69801686efa\\">\ucd94\uc0c1\ud654\ub294 \uc801\uc808\ud558\uac8c</a> \uae00\uc5d0\ub3c4 \ub9d0\ud588\ub4ef\uc774 \uc801\uc808\ud55c \ucd94\uc0c1\ud654\uac00 \uc911\uc694\ud558\uc9c0\ub9cc.. \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \ud6c4\uc5d0 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc774\ub098 \uacf5\uc6a9 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ub9cc\ub4e4 \ub54c\ub3c4 \uc0dd\uac01\ud574\uc57c \ud560 \uc218\ub3c4 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc774 \uae00\uc744 \ubcf4\uc2dc\uace0 \ud55c \ubc88 \uace0\ubbfc\ud574\ubcf4\ub294\uac8c \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"9d21cf6b-535e-4e27-906c-334242aa81c9\\" id=\\"9d21cf6b-535e-4e27-906c-334242aa81c9\\">Submenu\uc758 UX \uace0\ub824\uc810</h2><a href=\\"https://react-spectrum.adobe.com/blog/creating-a-pointer-friendly-submenu-experience.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react-spectrum.adobe.com/blog/creating-a-pointer-friendly-submenu-experience.html</a><p data-notion-block-id=\\"1f7fb221-be24-4137-a5ca-db248cd43fa5\\"><b>\uc2ec\uc724\uc12d</b>: \uc774\uc804\uc5d0 \uac00\uc838\uc654\ub358 \uae00(<a href=\\"https://ones-to-watch.ethansup.net/news/post/295b308b-5e8d-472d-8662-05f74c3cfed3\\">\uc0c1\ud638\uc791\uc6a9 \ubc94\uc704 \ub354 \uc88b\uac8c \ub9cc\ub4e4\uae30</a>)\uc911 \ud558\ub098\uc778 <a href=\\"https://ishadeed.com/article/target-size/#safe-triangle-target-areas\\">submenu \ud30c\ud2b8</a>\ub97c \ub354 \ub2e4\ub4ec\uc5b4\uc11c \ub354 \ub2e4\uc591\ud55c \uc694\uc778\uc744 \uc0dd\uac01\ud574\uc11c \uad6c\ud604\ud55c \uae00\uc785\ub2c8\ub2e4. UX \uac1c\uc120\uc5d0 \ub300\ud55c \uc0ac\uace0 \uacfc\uc815\uc744 \uc5ff\ubcfc \uc218 \uc788\uc73c\ubbc0\ub85c UX\uc5d0 \uad00\uc2ec\uc774 \uc788\ub2e4\uba74 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. \uc544\ub2c8\uba74 UX\ub97c \uac1c\uc120\ud558\uae30 \uc704\ud574 <a href=\\"https://react-spectrum.adobe.com/index.html\\">React spectrum</a>\uc744 \uc0ac\uc6a9\ud558\uc154\ub3c4 \ub418\uad6c\uc694.</p><h2 data-notion-block-id=\\"ff5c0721-0441-481d-8ffa-117886d482ac\\" id=\\"ff5c0721-0441-481d-8ffa-117886d482ac\\">\ube0c\ub77c\uc6b0\uc800\ub97c \ud0d0\uc9c0\ud558\uc9c0 \ub9c8\uc138\uc694.</h2><a href=\\"https://nielsleenheer.com/articles/2024/should-we-rely-on-browser-detection/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nielsleenheer.com/articles/2024/should-we-rely-on-browser-detection/</a><p data-notion-block-id=\\"4b6510f2-71a8-4de6-9169-553aac1c3df1\\"><b>\uc2ec\uc724\uc12d</b>: <a href=\\"https://web.dev/learn/privacy/fingerprinting\\">\ube0c\ub77c\uc6b0\uc800 Fingerprinting</a>\uc744 \ub9c9\uae30 \uc704\ud574 Chrome\ud300\uc740 <a href=\\"https://developers.google.com/privacy-sandbox/protections/user-agent?hl=ko\\">User Agent reduction</a>\uc744 \uc801\uc6a9\ud588\uc2b5\ub2c8\ub2e4. \uadf8 \ub300\uc548\uc73c\ub85c \ub098\uc628 <a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/User-Agent_Client_Hints_API\\">User Agent Client Hint</a>\uac00 \uc788\uc9c0\ub9cc \uc544\uc9c1 \uc774\uc5d0 \ub300\ud55c \ub17c\ub780\uc774 \ub9ce\uc2b5\ub2c8\ub2e4(<a href=\\"https://mozilla.github.io/standards-positions/#ua-client-hints\\">Firefox\uc758 \uc758\uacac</a>). \uadf8\ub798\uc11c \uc800\uc790\ub294 \ube0c\ub77c\uc6b0\uc800\ub97c \ud0d0\uc9c0\ud558\uace0 \uc9c0\uc6d0\ud558\uc9c0 \uc54a\ub294 \ube0c\ub77c\uc6b0\uc800\ub97c \ucc28\ub2e8\ud558\ub294 \ub300\uc2e0 \uae30\ub2a5\uc744 \uc9c0\uc6d0\ud558\ub294\uc9c0 \ud0d0\uc9c0\ub9cc \ud558\uace0 \ucc28\ub2e8\ud558\uc9c0 \uc54a\uae30\ub97c \uad8c\uc7a5\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"63e3cd18-2767-4720-9322-fd0b98c30eda\\" id=\\"63e3cd18-2767-4720-9322-fd0b98c30eda\\">\ud589\ub3d9\uc758 \uc9c0\uc5ed\uc131</h2><a href=\\"https://alexkondov.com/locality-of-behavior-react/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://alexkondov.com/locality-of-behavior-react/</a><p data-notion-block-id=\\"bc31aaef-8dbd-40ba-8e22-f809651900a0\\"><b>\uc2ec\uc724\uc12d</b>: \uc800\uc790\ub294 \uc790\uc2e0\uc758 \uae00(<a href=\\"https://ones-to-watch.ethansup.net/news/post/5c2a8faf-fd60-46cd-9bd2-d18b226e996f#5f302181-a327-4834-9ee5-047e17fe5a6e\\">\ub9ac\uc561\ud2b8\uc5d0\uc11c \uc544\ud0a4\ud14d\uccd0</a>)\uc744 \ubc14\ud0d5\uc73c\ub85c HTMX \uac1c\ubc1c\uc790\uac00 \ub9d0\ud55c <a href=\\"https://htmx.org/essays/locality-of-behaviour/\\">\ud589\ub3d9\uc758 \uc9c0\uc5ed\uc131</a>\uc744 React\uc5d0 \uc801\uc6a9\ud558\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc800\uc790\ub294 \uc774\ub984 \uc798 \uc9d3\ub294 \uac83\ub9cc \ub9d0\ud558\uc9c0\ub9cc \ubcc0\uc218\uc640 \ud568\uc218\uc758 \uc774\ub984\uc740 \uc5ed\ud560\uc744 \ub9d0\ud558\uace0 \uc788\uc73c\ubbc0\ub85c \ud30c\uc77c\ub9cc \ubcf4\uace0 \ud310\ub2e8\ud560 \uc218 \uc788\ub3c4\ub85d \uac15\ub825\ud558\uac8c \ub3c4\uc6c0\uc744 \uc90d\ub2c8\ub2e4. \uc774\ub984\uc5d0 \ub530\ub77c \uad6c\ud604\uc774 \ubcc0\ud560 \uc218\ub3c4 \uc788\uad6c\uc694. \uc774\ub984 \uc798 \uc9c0\uc5b4\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"ed9efc53-fcb1-4304-922a-9c9abcddaf4f\\" id=\\"ed9efc53-fcb1-4304-922a-9c9abcddaf4f\\">CSS Specificity\uc5d0 \ub300\ud55c \uc624\ud574</h2><a href=\\"https://www.bram.us/2024/05/05/misconceptions-about-css-specificity/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.bram.us/2024/05/05/misconceptions-about-css-specificity/</a><p data-notion-block-id=\\"38bad455-6b3d-4a1b-9935-ddaee65c6fba\\"><b>\uc2ec\uc724\uc12d</b>: CSS specificity\uc5d0 \ub300\ud574 \uc124\uba85\ud558\ub294 \uae00\uc740 \ub9e4\uc6b0 \ub9ce\uc2b5\ub2c8\ub2e4. \ub9ce\ub2e4\ubcf4\uba74 \uac1c\uc778\uc774 \ud574\uc11d\ud55c \uacb0\uacfc\uac00 \ub2e4\ub97c \uc218\ub3c4 \uc788\uace0, \uadf8 \uc911\uc5d0\ub294 \ub2e4\ub978 \uac1c\ub150\uc744 \ucd94\uac00\ub85c \ub123\uc5b4\uc11c \uc124\uba85\ud558\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 CSS Specificity\uc5d0 \ub300\ud55c \uc798\ubabb\ub41c \uac1c\ub150\uc744 \ubc14\ub85c\uc7a1\uc544\uc90d\ub2c8\ub2e4. \ud56d\uc0c1 \uad50\ucc28\uac80\uc99d\uc744 \ud558\ub294 \uac83\uc740 \uc911\uc694\ud558\ub2e4\uace0 \ub290\ub08d\ub2c8\ub2e4 \ud83d\ude02</p><h2 data-notion-block-id=\\"8362b2f7-286b-48eb-b663-9a13895044e7\\" id=\\"8362b2f7-286b-48eb-b663-9a13895044e7\\">CSS minify\ub97c \uc2e0\uacbd\uc4f0\uc9c0 \uc54a\ub294 \uc774\uc720</h2><a href=\\"https://blog.sentry.io/why-dont-we-talk-about-minifying-css/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.sentry.io/why-dont-we-talk-about-minifying-css/</a><p data-notion-block-id=\\"0e02dede-b5c8-4fd3-8d7f-1f84908c8608\\">\uc555\ucd95, HTTP2\uc758 \ub2e4\uc911\ud654\uac00 \ubc1c\ub2ec\ud588\uace0, \ud2b9\ud788 \ubaa8\ub358 \ud504\ub808\uc784\uc6cc\ud06c\uc758 code spliting, minify, optimzing\uc744 \ubaa8\ub450 \ub2f4\ub2f9\ud574\uc11c CSS minify\uc5d0 \ub354 \uc2e0\uacbd\uc4f0\uc9c0 \uc54a\uc744 \uc218 \uc788\uac8c \ub418\uc5c8\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"e0c73826-d5a9-4fc4-a7b4-43410159be2c\\" id=\\"e0c73826-d5a9-4fc4-a7b4-43410159be2c\\">Gulp is back.</h2><a href=\\"https://medium.com/gulpjs/announcing-gulp-v5-c67d077dbdb7\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/gulpjs/announcing-gulp-v5-c67d077dbdb7</a><p data-notion-block-id=\\"15ef964e-ec82-4e0f-bb40-24f5069babe0\\">\uc8fd\uc740\uc904\ub9cc \uc54c\uc558\ub358 Gulp\uc774 \ub3cc\uc544\uc654\uc2b5\ub2c8\ub2e4. Node 8 \uc548 \uc368\ub3c4 \ub418\uaca0\ub124\uc694 \ud83c\udf89</p><h2 data-notion-block-id=\\"9104b914-c2e2-4996-84f6-a8cb82cb8a42\\" id=\\"9104b914-c2e2-4996-84f6-a8cb82cb8a42\\">Chrome\uc758 \uc0ac\uc804\ub80c\ub354\ub9c1 API</h2><a href=\\"https://developer.chrome.com/blog/speculation-rules-improvements?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/blog/speculation-rules-improvements?hl=ko</a><p data-notion-block-id=\\"5e362649-1f8d-4b5a-8eed-1cc4d88b2cae\\">Chrome\uc5d0\uc11c\ub294 prerender\ub97c \uc704\ud574 Speculation Rules API\ub97c \uc608\uc804\uc5d0 \ub9cc\ub4e4\uc5c8\uace0, \uadf8\uc5d0 \ub300\ud55c \uc5c5\ub370\uc774\ud2b8\ub97c \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4. \ubb3c\ub860 Chrome \uae30\ubc18 \ube0c\ub77c\uc6b0\uc800\ub9cc \uc791\ub3d9\ud558\uace0, <a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTML/Attributes/rel/prerender\\"><code>&#x3C;link rel=\\"prerender\\"></code></a><a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTML/Attributes/rel/prerender\\">\ubc29\uc2dd</a>\uc740 deprecated\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"9c9a8c78-bc10-49aa-92bc-833d7817f250\\" id=\\"9c9a8c78-bc10-49aa-92bc-833d7817f250\\">Effect\ub294 \ud568\uc218\ud615 TypeScript\uc758 \uafc8\uc744 \uafb8\ub294\uac00</h2><a href=\\"https://effect.website/blog/effect-3.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://effect.website/blog/effect-3.0</a><p data-notion-block-id=\\"3f6ed753-6318-42b9-a6be-d03cbdc41779\\">\uc608\uc804\uc758 \uae00(<a href=\\"https://ones-to-watch.ethansup.net/news/post/295b308b-5e8d-472d-8662-05f74c3cfed3#5e16c43a-28c7-4497-b656-96ac1c8494c1\\">ReScript\ub294 TypeScript\uc758 \uafc8\uc744 \uafb8\ub294\uac00</a>)\uc5d0\uc11c \uc18c\uac1c\ud55c \ube44\uc2b7\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\uc9c0\ub9cc Effect\ub294 \uc5b8\uc5b4\ub97c \uc0c8\ub85c \ub9cc\ub4e4\uc9c0\ub294 \uc54a\uace0 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0\uc11c \ub9ce\uc740 \uae30\ub2a5\uc744 \uc81c\uacf5\ud558\ub294 \ud615\ud0dc\ub85c \ud568\uc218\ud615 \ud504\ub85c\uadf8\ub798\ubc0d\uacfc Type \uc2dc\uc2a4\ud15c \uac15\ud654, \ub3d9\uc2dc\uc131 \uac15\ud654\ub97c \uad6c\ud604\ud588\uc2b5\ub2c8\ub2e4. \ubb3c\ub860 ReScript\uc640 \ub611\uac19\uc774 \ubc30\uc6b0\ub294\ub370\uc5d0 \ub9e4\uc6b0 \ub9ce\uc740 \uc2dc\uac04\uc774 \ub4e4\uace0, \uc774 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0 \ud06c\uac8c \uc885\uc18d\ub41c\ub2e4\ub294 \uc810\uc740 \ub2e8\uc810\uc73c\ub85c \uaf3d\ud788\uaca0\uc9c0\ub9cc\uc694.</p><h2 data-notion-block-id=\\"fb3a353f-c31c-4347-b3ae-5d03183eb9b4\\" id=\\"fb3a353f-c31c-4347-b3ae-5d03183eb9b4\\">Can I use..?</h2><a href=\\"https://www.caniemail.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.caniemail.com/</a><a href=\\"https://caniwebview.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://caniwebview.com/</a><p data-notion-block-id=\\"38ea460c-15e6-4d4b-ba75-0f3cdfa43fd4\\">Can I use\uc758 Email, Webview\ud310\uc785\ub2c8\ub2e4. \ub098\uc911\uc5d0 \ub370\uc774\ud130\uac00 \ubaa8\ub450 \ubaa8\uc774\uba74 \uc88b\uc740 \uc0ac\uc774\ud2b8\uac00 \ub418\uaca0\ub124\uc694. \ud83d\ude03</p>"}')}}]);